-- Góc Trọ Database V1.11 CORE runtime validator.
-- Populated-target safe: does not require V1.8 seed/demo rows or demo IDs.
-- Probe business rows use explicit max+1 IDs and are rolled back by the outer transaction.
-- Run during a quiet maintenance window; locks prevent concurrent ID collisions.
BEGIN;
SET LOCAL TIME ZONE 'UTC';
SET LOCAL lock_timeout='10s';
LOCK TABLE owners,accounts,properties,rooms,residents,contracts,invoices,amenities,amenity_price_history,
 parking_areas,parking_slots,vehicles,parking_slot_assignments,utility_tariffs,utility_tariff_versions,
 electricity_tariff_tiers,property_facilities,property_pricing_items,property_price_versions,
 property_flexible_service_configurations,flexible_service_charges,parking_entitlements,meter_readings,invoice_meter_reading_snapshots,
 invoice_items,invoice_item_electricity_tiers,auth_sessions,resident_service_bookings IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE validator_results(test_name text PRIMARY KEY,passed boolean NOT NULL) ON COMMIT DROP;
CREATE FUNCTION pg_temp.assert_true(n text,c boolean) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 IF c IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'VALIDATION FAIL: %',n; END IF;
 INSERT INTO validator_results VALUES(n,true); RAISE NOTICE 'PASS: %',n;
END $$;
CREATE FUNCTION pg_temp.assert_rejected(n text,s text,states text[]) RETURNS void LANGUAGE plpgsql AS $$
DECLARE st text;
BEGIN
 BEGIN EXECUTE s;
 EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st=RETURNED_SQLSTATE;
  IF st=ANY(states) THEN INSERT INTO validator_results VALUES(n,true); RAISE NOTICE 'PASS: % (SQLSTATE %)',n,st; RETURN; END IF;
  RAISE EXCEPTION 'VALIDATION FAIL: %, expected %, got %',n,states,st;
 END;
 RAISE EXCEPTION 'VALIDATION FAIL: % accepted unexpectedly',n;
END $$;
CREATE FUNCTION pg_temp.assert_deferred_rejected(n text,s text,states text[]) RETURNS void LANGUAGE plpgsql AS $$
DECLARE st text;
BEGIN
 BEGIN
  EXECUTE s;
  SET CONSTRAINTS ALL IMMEDIATE;
 EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st=RETURNED_SQLSTATE;
  IF st=ANY(states) THEN INSERT INTO validator_results VALUES(n,true); RAISE NOTICE 'PASS: % (SQLSTATE %)',n,st; RETURN; END IF;
  RAISE EXCEPTION 'VALIDATION FAIL: %, expected %, got %',n,states,st;
 END;
 SET CONSTRAINTS ALL DEFERRED;
 RAISE EXCEPTION 'VALIDATION FAIL: % accepted unexpectedly',n;
END $$;
CREATE FUNCTION pg_temp.alloc_id(t text,c text) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE v bigint;
BEGIN EXECUTE format('SELECT COALESCE(max(%I),0)+1 FROM public.%I',c,t) INTO v; RETURN v; END $$;
CREATE TEMP TABLE probe_context(
 owner_a bigint,owner_b bigint,account_a bigint,account_b bigint,property_a bigint,property_b bigint,
 room_a bigint,room_b bigint,resident_a bigint,resident_b bigint,contract_a bigint,contract_b bigint,
 parking_area_a bigint,slot_a bigint,vehicle_a bigint,amenity_a bigint,amenity_price_a bigint,
 invoice_draft bigint,tariff_e bigint,version_e bigint,tier_e1 bigint,tier_e2 bigint,
 tariff_w bigint,version_w bigint,fixed_item bigint,fixed_version bigint,flex_item bigint,flex_version bigint,
 parking_item bigint,parking_version bigint,ent_paid bigint,ent_free bigint,ent_card_paid bigint,ent_card_free bigint,
 ent_legacy bigint,meter_e_open bigint,meter_e_end bigint,meter_w_open bigint,meter_w_end bigint
) ON COMMIT DROP;
DO $$
DECLARE c probe_context%ROWTYPE; s text:=txid_current()::text;
BEGIN
 c.owner_a:=pg_temp.alloc_id('owners','owner_id'); INSERT INTO owners(owner_id,display_name) OVERRIDING SYSTEM VALUE VALUES(c.owner_a,'V18 core A');
 c.owner_b:=pg_temp.alloc_id('owners','owner_id'); INSERT INTO owners(owner_id,display_name) OVERRIDING SYSTEM VALUE VALUES(c.owner_b,'V18 core B');
 c.account_a:=pg_temp.alloc_id('accounts','account_id'); INSERT INTO accounts(account_id,owner_id,role,email,password_hash) OVERRIDING SYSTEM VALUE VALUES(c.account_a,c.owner_a,'admin','v18a-'||s||'@invalid.test','validator');
 c.account_b:=pg_temp.alloc_id('accounts','account_id'); INSERT INTO accounts(account_id,owner_id,role,email,password_hash) OVERRIDING SYSTEM VALUE VALUES(c.account_b,c.owner_b,'admin','v18b-'||s||'@invalid.test','validator');
 c.property_a:=pg_temp.alloc_id('properties','property_id'); INSERT INTO properties(property_id,owner_id,property_code,name,province,address) OVERRIDING SYSTEM VALUE VALUES(c.property_a,c.owner_a,'V18A-'||s,'V18 core A','TEST','validator');
 c.property_b:=pg_temp.alloc_id('properties','property_id'); INSERT INTO properties(property_id,owner_id,property_code,name,province,address) OVERRIDING SYSTEM VALUE VALUES(c.property_b,c.owner_b,'V18B-'||s,'V18 core B','TEST','validator');
 c.room_a:=pg_temp.alloc_id('rooms','room_id'); INSERT INTO rooms(room_id,property_id,owner_id,room_code,area_m2,default_rent,default_capacity) OVERRIDING SYSTEM VALUE VALUES(c.room_a,c.property_a,c.owner_a,'V18A-'||s,10,100000,2);
 c.room_b:=pg_temp.alloc_id('rooms','room_id'); INSERT INTO rooms(room_id,property_id,owner_id,room_code,area_m2,default_rent,default_capacity) OVERRIDING SYSTEM VALUE VALUES(c.room_b,c.property_b,c.owner_b,'V18B-'||s,10,100000,2);
 c.resident_a:=pg_temp.alloc_id('residents','resident_id'); INSERT INTO residents(resident_id,owner_id,full_name) OVERRIDING SYSTEM VALUE VALUES(c.resident_a,c.owner_a,'V17 core resident A');
 c.resident_b:=pg_temp.alloc_id('residents','resident_id'); INSERT INTO residents(resident_id,owner_id,full_name) OVERRIDING SYSTEM VALUE VALUES(c.resident_b,c.owner_b,'V17 core resident B');
 c.contract_a:=pg_temp.alloc_id('contracts','contract_id'); INSERT INTO contracts(contract_id,contract_no,room_id,property_id,owner_id,representative_resident_id,start_date,end_date,status,revision,rent_amount,deposit_amount,resident_capacity) OVERRIDING SYSTEM VALUE VALUES(c.contract_a,'V17A-'||s,c.room_a,c.property_a,c.owner_a,c.resident_a,DATE '2027-01-01',DATE '2027-12-31','draft',0,100000,0,2);
 c.contract_b:=pg_temp.alloc_id('contracts','contract_id'); INSERT INTO contracts(contract_id,contract_no,room_id,property_id,owner_id,representative_resident_id,start_date,end_date,status,revision,rent_amount,deposit_amount,resident_capacity) OVERRIDING SYSTEM VALUE VALUES(c.contract_b,'V17B-'||s,c.room_b,c.property_b,c.owner_b,c.resident_b,DATE '2027-01-01',DATE '2027-12-31','draft',0,100000,0,2);
 c.parking_area_a:=pg_temp.alloc_id('parking_areas','parking_area_id'); INSERT INTO parking_areas(parking_area_id,property_id,owner_id,name) OVERRIDING SYSTEM VALUE VALUES(c.parking_area_a,c.property_a,c.owner_a,'V17 core area');
 c.slot_a:=pg_temp.alloc_id('parking_slots','parking_slot_id'); INSERT INTO parking_slots(parking_slot_id,parking_area_id,property_id,owner_id,slot_code) OVERRIDING SYSTEM VALUE VALUES(c.slot_a,c.parking_area_a,c.property_a,c.owner_a,'V17A-'||s);
 c.vehicle_a:=pg_temp.alloc_id('vehicles','vehicle_id'); INSERT INTO vehicles(vehicle_id,resident_id,owner_id,vehicle_type) OVERRIDING SYSTEM VALUE VALUES(c.vehicle_a,c.resident_a,c.owner_a,'validator');
 c.amenity_a:=pg_temp.alloc_id('amenities','amenity_id'); INSERT INTO amenities(amenity_id,property_id,owner_id,amenity_type,name,registration_type) OVERRIDING SYSTEM VALUE VALUES(c.amenity_a,c.property_a,c.owner_a,'pool','V17 core amenity','subscription');
 c.amenity_price_a:=pg_temp.alloc_id('amenity_price_history','amenity_price_id'); INSERT INTO amenity_price_history(amenity_price_id,amenity_id,effective_at,price_amount) OVERRIDING SYSTEM VALUE VALUES(c.amenity_price_a,c.amenity_a,now(),1000);
 c.invoice_draft:=pg_temp.alloc_id('invoices','invoice_id'); INSERT INTO invoices(invoice_id,invoice_no,contract_id,property_id,owner_id,period_start,period_end,rent_amount,electricity_amount,water_amount,service_amount,total_amount,status,snapshot_kind) OVERRIDING SYSTEM VALUE VALUES(c.invoice_draft,'V17D-'||s,c.contract_a,c.property_a,c.owner_a,DATE '2027-01-01',DATE '2027-01-31',0,0,0,0,0,'draft','NOT_FINALIZED');
 c.tariff_e:=pg_temp.alloc_id('utility_tariffs','utility_tariff_id'); INSERT INTO utility_tariffs(utility_tariff_id,owner_id,property_id,utility_type,code,name) OVERRIDING SYSTEM VALUE VALUES(c.tariff_e,c.owner_a,c.property_a,'ELECTRICITY','V17E-'||s,'Core Electricity');
 c.version_e:=pg_temp.alloc_id('utility_tariff_versions','utility_tariff_version_id'); INSERT INTO utility_tariff_versions(utility_tariff_version_id,utility_tariff_id,owner_id,property_id,utility_type,version_no,effective_from,unit,calculation_mode,created_by_account_id) OVERRIDING SYSTEM VALUE VALUES(c.version_e,c.tariff_e,c.owner_a,c.property_a,'ELECTRICITY',1,DATE '2027-01-01','kWh','PROGRESSIVE',c.account_a);
 c.tier_e1:=pg_temp.alloc_id('electricity_tariff_tiers','electricity_tariff_tier_id'); INSERT INTO electricity_tariff_tiers(electricity_tariff_tier_id,utility_tariff_version_id,tier_no,lower_kwh,upper_kwh,unit_price) OVERRIDING SYSTEM VALUE VALUES(c.tier_e1,c.version_e,1,0,50,1000);
 c.tier_e2:=pg_temp.alloc_id('electricity_tariff_tiers','electricity_tariff_tier_id'); INSERT INTO electricity_tariff_tiers(electricity_tariff_tier_id,utility_tariff_version_id,tier_no,lower_kwh,upper_kwh,unit_price) OVERRIDING SYSTEM VALUE VALUES(c.tier_e2,c.version_e,2,50,NULL,1500);
 UPDATE utility_tariff_versions SET published_at=now(),published_by_account_id=c.account_a WHERE utility_tariff_version_id=c.version_e;
 c.tariff_w:=pg_temp.alloc_id('utility_tariffs','utility_tariff_id'); INSERT INTO utility_tariffs(utility_tariff_id,owner_id,property_id,utility_type,code,name) OVERRIDING SYSTEM VALUE VALUES(c.tariff_w,c.owner_a,c.property_a,'WATER','V17W-'||s,'Core Water');
 c.version_w:=pg_temp.alloc_id('utility_tariff_versions','utility_tariff_version_id'); INSERT INTO utility_tariff_versions(utility_tariff_version_id,utility_tariff_id,owner_id,property_id,utility_type,version_no,effective_from,unit,calculation_mode,flat_unit_price,created_by_account_id) OVERRIDING SYSTEM VALUE VALUES(c.version_w,c.tariff_w,c.owner_a,c.property_a,'WATER',1,DATE '2027-01-01','m3','FLAT',12000,c.account_a);
 UPDATE utility_tariff_versions SET published_at=now(),published_by_account_id=c.account_a WHERE utility_tariff_version_id=c.version_w;
 c.fixed_item:=pg_temp.alloc_id('property_pricing_items','property_pricing_item_id'); INSERT INTO property_pricing_items(property_pricing_item_id,owner_id,property_id,kind,code,name,unit) OVERRIDING SYSTEM VALUE VALUES(c.fixed_item,c.owner_a,c.property_a,'FIXED_SERVICE','V17F-'||s,'Core fixed','room/period');
 c.fixed_version:=pg_temp.alloc_id('property_price_versions','property_price_version_id'); INSERT INTO property_price_versions(property_price_version_id,property_pricing_item_id,owner_id,property_id,kind,version_no,effective_from,unit_price,published_at,published_by_account_id,reason,created_by_account_id) OVERRIDING SYSTEM VALUE VALUES(c.fixed_version,c.fixed_item,c.owner_a,c.property_a,'FIXED_SERVICE',1,DATE '2027-01-01',10000,now(),c.account_a,'validator',c.account_a);
 c.flex_item:=pg_temp.alloc_id('property_pricing_items','property_pricing_item_id'); INSERT INTO property_pricing_items(property_pricing_item_id,owner_id,property_id,kind,code,name,unit) OVERRIDING SYSTEM VALUE VALUES(c.flex_item,c.owner_a,c.property_a,'FLEXIBLE_SERVICE','V17X-'||s,'Core flexible','use');
 INSERT INTO property_flexible_service_configurations(property_pricing_item_id,owner_id,property_id,service_mode,opens_at,closes_at,open_monday,open_tuesday,open_wednesday,open_thursday,open_friday,open_saturday,open_sunday,slot_duration_minutes,capacity_per_slot) VALUES(c.flex_item,c.owner_a,c.property_a,'BOOKING',TIME '08:00',TIME '22:00',true,true,true,true,true,true,true,30,2);
 c.flex_version:=pg_temp.alloc_id('property_price_versions','property_price_version_id'); INSERT INTO property_price_versions(property_price_version_id,property_pricing_item_id,owner_id,property_id,kind,version_no,effective_from,unit_price,published_at,published_by_account_id,reason,created_by_account_id) OVERRIDING SYSTEM VALUE VALUES(c.flex_version,c.flex_item,c.owner_a,c.property_a,'FLEXIBLE_SERVICE',1,DATE '2027-01-01',20000,now(),c.account_a,'validator',c.account_a);
 c.parking_item:=pg_temp.alloc_id('property_pricing_items','property_pricing_item_id'); INSERT INTO property_pricing_items(property_pricing_item_id,owner_id,property_id,kind,code,name,unit) OVERRIDING SYSTEM VALUE VALUES(c.parking_item,c.owner_a,c.property_a,'PARKING','V17P-'||s,'Core parking','vehicle/period');
 c.parking_version:=pg_temp.alloc_id('property_price_versions','property_price_version_id'); INSERT INTO property_price_versions(property_price_version_id,property_pricing_item_id,owner_id,property_id,kind,version_no,effective_from,unit_price,published_at,published_by_account_id,reason,created_by_account_id) OVERRIDING SYSTEM VALUE VALUES(c.parking_version,c.parking_item,c.owner_a,c.property_a,'PARKING',1,DATE '2027-01-01',80000,now(),c.account_a,'validator',c.account_a);
 c.ent_free:=pg_temp.alloc_id('parking_entitlements','parking_entitlement_id'); INSERT INTO parking_entitlements(parking_entitlement_id,owner_id,property_id,entitlement_type,billability,code,name) OVERRIDING SYSTEM VALUE VALUES(c.ent_free,c.owner_a,c.property_a,'FREE_SLOT','FREE','V17FREE-'||s,'Core free');
 c.ent_paid:=pg_temp.alloc_id('parking_entitlements','parking_entitlement_id'); INSERT INTO parking_entitlements(parking_entitlement_id,owner_id,property_id,entitlement_type,billability,property_pricing_item_id,pricing_kind,code,name) OVERRIDING SYSTEM VALUE VALUES(c.ent_paid,c.owner_a,c.property_a,'PAID_SLOT','PAID',c.parking_item,'PARKING','V17PAID-'||s,'Core paid');
 c.ent_card_paid:=pg_temp.alloc_id('parking_entitlements','parking_entitlement_id'); INSERT INTO parking_entitlements(parking_entitlement_id,owner_id,property_id,entitlement_type,billability,property_pricing_item_id,pricing_kind,code,name) OVERRIDING SYSTEM VALUE VALUES(c.ent_card_paid,c.owner_a,c.property_a,'MOTORCYCLE_VEHICLE_CARD','PAID',c.parking_item,'PARKING','V17CP-'||s,'Core paid card');
 c.ent_card_free:=pg_temp.alloc_id('parking_entitlements','parking_entitlement_id'); INSERT INTO parking_entitlements(parking_entitlement_id,owner_id,property_id,entitlement_type,billability,code,name) OVERRIDING SYSTEM VALUE VALUES(c.ent_card_free,c.owner_a,c.property_a,'APARTMENT_VEHICLE_CARD','FREE','V17CF-'||s,'Core free card');
 c.ent_legacy:=pg_temp.alloc_id('parking_entitlements','parking_entitlement_id'); INSERT INTO parking_entitlements(parking_entitlement_id,owner_id,property_id,entitlement_type,billability,code,name) OVERRIDING SYSTEM VALUE VALUES(c.ent_legacy,c.owner_a,c.property_a,'LEGACY_UNCLASSIFIED','UNCLASSIFIED','V17LEG-'||s,'Core legacy');
 c.meter_e_open:=pg_temp.alloc_id('meter_readings','meter_reading_id'); INSERT INTO meter_readings(meter_reading_id,owner_id,property_id,room_id,contract_id,utility_type,value,reading_at,actor_account_id) OVERRIDING SYSTEM VALUE VALUES(c.meter_e_open,c.owner_a,c.property_a,c.room_a,c.contract_a,'ELECTRICITY',10,now()-interval '1 day',c.account_a);
 c.meter_e_end:=pg_temp.alloc_id('meter_readings','meter_reading_id'); INSERT INTO meter_readings(meter_reading_id,owner_id,property_id,room_id,contract_id,utility_type,value,reading_at,actor_account_id) OVERRIDING SYSTEM VALUE VALUES(c.meter_e_end,c.owner_a,c.property_a,c.room_a,c.contract_a,'ELECTRICITY',11.125,now(),c.account_a);
 c.meter_w_open:=pg_temp.alloc_id('meter_readings','meter_reading_id'); INSERT INTO meter_readings(meter_reading_id,owner_id,property_id,room_id,contract_id,utility_type,value,reading_at,actor_account_id) OVERRIDING SYSTEM VALUE VALUES(c.meter_w_open,c.owner_a,c.property_a,c.room_a,c.contract_a,'WATER',5,now()-interval '1 day',c.account_a);
 c.meter_w_end:=pg_temp.alloc_id('meter_readings','meter_reading_id'); INSERT INTO meter_readings(meter_reading_id,owner_id,property_id,room_id,contract_id,utility_type,value,reading_at,actor_account_id) OVERRIDING SYSTEM VALUE VALUES(c.meter_w_end,c.owner_a,c.property_a,c.room_a,c.contract_a,'WATER',5.5,now(),c.account_a);
 INSERT INTO probe_context SELECT c.owner_a,c.owner_b,c.account_a,c.account_b,c.property_a,c.property_b,c.room_a,c.room_b,c.resident_a,c.resident_b,c.contract_a,c.contract_b,c.parking_area_a,c.slot_a,c.vehicle_a,c.amenity_a,c.amenity_price_a,c.invoice_draft,c.tariff_e,c.version_e,c.tier_e1,c.tier_e2,c.tariff_w,c.version_w,c.fixed_item,c.fixed_version,c.flex_item,c.flex_version,c.parking_item,c.parking_version,c.ent_paid,c.ent_free,c.ent_card_paid,c.ent_card_free,c.ent_legacy,c.meter_e_open,c.meter_e_end,c.meter_w_open,c.meter_w_end;
END $$;
DO $$
DECLARE c probe_context%ROWTYPE; v bigint; v2 bigint; v3 bigint; inv bigint; item bigint; tier bigint; fc bigint; snap bigint; assignment bigint; other_inv bigint; other_assignment bigint; other_slot bigint; other_vehicle bigint; s text:=txid_current()::text;
BEGIN
 SELECT * INTO c FROM probe_context;
 PERFORM pg_temp.assert_true('CORE-01 exactly 46 public tables',(SELECT count(*)=46 FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE'));
 PERFORM pg_temp.assert_true('CORE-02 all twelve V1.7 tables exist',(SELECT count(*)=12 FROM information_schema.tables WHERE table_schema='public' AND table_name IN ('utility_tariffs','utility_tariff_versions','electricity_tariff_tiers','property_facilities','property_pricing_items','property_price_versions','flexible_service_charges','parking_entitlements','meter_readings','invoice_meter_reading_snapshots','invoice_items','invoice_item_electricity_tiers')));
 PERFORM pg_temp.assert_true('CORE-03 original 28 tables preserved',(SELECT count(*)=28 FROM information_schema.tables WHERE table_schema='public' AND table_name IN ('owners','accounts','account_invitations','properties','rooms','room_images','residents','room_residents','contracts','contract_change_history','contract_documents','contract_idempotency_requests','invoices','payment_transactions','invoice_zalo_oa_send_logs','amenities','amenity_price_history','amenity_subscriptions','amenity_subscription_cycles','parking_areas','parking_slots','parking_slot_assignments','vehicles','complaints','complaint_history','contact_requests','notifications','notification_preferences')));
 PERFORM pg_temp.assert_true('CORE-04 invoices.snapshot_kind exists',EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='invoices' AND column_name='snapshot_kind'));
 PERFORM pg_temp.assert_true('CORE-05 parking assignment entitlement_id exists',EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='parking_slot_assignments' AND column_name='entitlement_id'));
 PERFORM pg_temp.assert_true('CORE-06 tariff CHECKs and tier publication trigger exist',(SELECT count(*)>=7 FROM pg_constraint WHERE contype='c' AND conrelid IN ('public.utility_tariffs'::regclass,'public.utility_tariff_versions'::regclass,'public.electricity_tariff_tiers'::regclass)) AND EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='utility_tariff_publish_tiers' AND NOT tgisinternal));
 PERFORM pg_temp.assert_true('CORE-07 snapshot lifecycle CHECK exists',EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.invoices'::regclass AND conname='invoices_snapshot_kind_lifecycle'));
 PERFORM pg_temp.assert_true('CORE-08 immutability guards exist',(SELECT count(*)>=8 FROM pg_trigger WHERE NOT tgisinternal AND tgname IN ('utility_tariff_versions_immutable','electricity_tiers_immutable','property_price_versions_immutable','amenity_price_history_immutable','meter_readings_append_only','invoice_meter_snapshots_append_only','invoice_items_finalized_guard','invoice_tiers_finalized_guard','invoices_financial_guard')));
 PERFORM pg_temp.assert_rejected('CORE-09 invalid utility type rejected',format('INSERT INTO utility_tariffs(utility_tariff_id,owner_id,property_id,utility_type,code,name) OVERRIDING SYSTEM VALUE VALUES(%s,%s,%s,''GAS'',''bad-%s'',''bad'')',pg_temp.alloc_id('utility_tariffs','utility_tariff_id'),c.owner_a,c.property_a,s),ARRAY['23514']);
 PERFORM pg_temp.assert_true('CORE-10 valid progressive Electricity tiers publish',EXISTS(SELECT 1 FROM utility_tariff_versions WHERE utility_tariff_version_id=c.version_e AND published_at IS NOT NULL) AND (SELECT count(*)=2 FROM electricity_tariff_tiers WHERE utility_tariff_version_id=c.version_e));
 PERFORM pg_temp.assert_true('CORE-11 valid flat Water m3 tariff accepted',EXISTS(SELECT 1 FROM utility_tariff_versions WHERE utility_tariff_version_id=c.version_w AND unit='m3' AND calculation_mode='FLAT' AND flat_unit_price=12000 AND published_at IS NOT NULL));
 PERFORM pg_temp.assert_rejected('CORE-12 negative Water rate rejected',format('INSERT INTO utility_tariff_versions(utility_tariff_version_id,utility_tariff_id,owner_id,property_id,utility_type,version_no,effective_from,unit,calculation_mode,flat_unit_price,created_by_account_id) OVERRIDING SYSTEM VALUE VALUES(%s,%s,%s,%s,''WATER'',2,CURRENT_DATE,''m3'',''FLAT'',-1,%s)',pg_temp.alloc_id('utility_tariff_versions','utility_tariff_version_id'),c.tariff_w,c.owner_a,c.property_a,c.account_a),ARRAY['23514']);
 PERFORM pg_temp.assert_rejected('CORE-13 invalid utility/unit shape rejected',format('INSERT INTO utility_tariff_versions(utility_tariff_version_id,utility_tariff_id,owner_id,property_id,utility_type,version_no,effective_from,unit,calculation_mode,flat_unit_price,created_by_account_id) OVERRIDING SYSTEM VALUE VALUES(%s,%s,%s,%s,''ELECTRICITY'',2,CURRENT_DATE,''m3'',''FLAT'',100,%s)',pg_temp.alloc_id('utility_tariff_versions','utility_tariff_version_id'),c.tariff_e,c.owner_a,c.property_a,c.account_a),ARRAY['23514']);
